insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v001', 'abundant', 'Lương chưa về mà bill thì ABUNDANT vãi, nhìn cái app ngân hàng mà muốn trầm cảm.', 'Dư thừa, nhiều hơn cần thiết', 'beginner', 850),
