  ('v010', 'subtle', 'Bồ tôi bảo ''Em sao cũng được'' là một dấu hiệu SUBTLE rằng tôi sắp tới số rồi.', 'Tinh tế, khó nhận ra', 'beginner', 930),
  ('v011', 'meticulous', 'Phải METICULOUS lắm mới tìm ra được cái lỗi logic mà thằng dev cũ giấu kỹ như vậy.', 'Tỉ mỉ, cẩn thận', 'intermediate', 1050),
  ('v012', 'ubiquitous', 'Mấy cái app giao đồ ăn giờ UBIQUITOUS quá, bước ra ngõ là thấy shipper đứng đầy đường.', 'Phổ biến khắp nơi', 'intermediate', 1080),
  ('v013', 'ephemeral', 'Cái cảm giác giàu sang khi vừa nhận lương thật là EPHEMERAL, trả nợ xong là hết.', 'Phù du, ngắn ngủi', 'intermediate', 1100),
  ('v014', 'eloquent', 'Hắn ta giải trình về lý do đi trễ ELOQUENT đến mức sếp quên luôn định phạt.', 'Hùng biện, lưu loát', 'intermediate', 1020),
  ('v015', 'plausible', 'Lý do ''nhà mất mạng'' nghe có vẻ PLAUSIBLE đấy, nhưng tiếc là tôi thấy ông đang on Facebook.', 'Hợp lý, đáng tin', 'intermediate', 1010),
  ('v016', 'scrutinize', 'Mỗi lần push code là sợ bị ông lead SCRUTINIZE từng dòng, soi còn hơn mẹ soi con dâu.', 'Xem xét kỹ lưỡng', 'intermediate', 1040),
