  ('v019', 'mundane', 'Mấy cái task MUNDANE như update data này làm tốn thời gian mà chẳng học thêm được gì.', 'Tầm thường, nhàm chán', 'intermediate', 1000),
  ('v020', 'inherent', 'Làm freelance thì rủi ro bị bùng tiền là một đặc điểm INHERENT rồi, phải chịu thôi.', 'Vốn có, cố hữu', 'intermediate', 1070),
  ('v021', 'conundrum', 'Một cái CONUNDRUM: Muốn có kinh nghiệm thì phải có việc, mà muốn có việc thì phải có kinh nghiệm?', 'Vấn đề hóc búa', 'intermediate', 1150),
  ('v022', 'exacerbate', 'Đang stress mà còn gặp thêm mấy tin nhắn ''Deadline tới đâu rồi em'' chỉ làm EXACERBATE tình hình thôi.', 'Làm tệ hại thêm', 'intermediate', 1180),
  ('v023', 'mitigate', 'Uống một ly trà sữa để MITIGATE sự mệt mỏi sau 8 tiếng dán mắt vào màn hình.', 'Giảm nhẹ, làm dịu', 'intermediate', 1120),
  ('v024', 'nuance', 'Phải hiểu được cái NUANCE trong lời nói của sếp, ''Anh thấy cũng được'' thường có nghĩa là ''Dở tệ''.', 'Sắc thái nhỏ', 'intermediate', 1140),
  ('v025', 'prolific', 'Ông nội này PROLIFIC vãi, tuần nào cũng thấy ra 2-3 cái open source project mới.', 'Hiệu suất cao, đẻ nhiều', 'intermediate', 1160),
  ('v026', 'redundant', 'Code gì mà REDUNDANT quá vậy, mười mấy dòng này gom lại thành 1 dòng là xong rồi.', 'Thừa thãi', 'intermediate', 1110),
  ('v027', 'tangible', 'Học xong khóa này hy vọng sẽ có kết quả TANGIBLE chút, chứ đừng có mỗi cái certificate ảo.', 'Hữu hình, rõ rệt', 'intermediate', 1130),
  ('v028', 'zenith', 'Cái app này đạt ZENITH về số lượng người dùng vào năm ngoái, giờ thì đang tụt dốc.', 'Đỉnh cao', 'intermediate', 1190),
  ('v029', 'coherent', 'Nói chuyện kiểu gì mà chẳng thấy COHERENT tí nào, trước sau đá nhau chan chát.', 'Mạch lạc, logic', 'intermediate', 1170),
  ('v030', 'arbitrary', 'Việc chọn màu cho cái button này cảm giác hoàn toàn ARBITRARY, chẳng theo cái design system nào cả.', 'Tùy hứng, tùy tiện', 'intermediate', 1100),
  ('v031', 'belligerent', 'Mấy ông thần nhậu vào là bắt đầu BELLIGERENT, nhìn ai cũng muốn kiếm chuyện làm như mình là hổ báo trường mẫu giáo.', 'Hiếu chiến, hung hăng', 'advanced', 1250),
  ('v032', 'elucidate', 'Ông giải thích nãy giờ tôi vẫn chưa hiểu, ELUCIDATE lại giùm cái logic tại sao cái component này lại render 10 lần vậy?', 'Làm sáng tỏ, giải thích rõ', 'advanced', 1220),
  ('v033', 'esoteric', 'Mấy cái kiến thức về blockchain này ban đầu nghe có vẻ ESOTERIC, nhưng đọc kỹ thì... vẫn thấy khó hiểu vãi.', 'Bí truyền, chuyên sâu khó hiểu', 'advanced', 1280),
  ('v034', 'gregarious', 'Mấy đứa GREGARIOUS đi networking lúc nào cũng như cá gặp nước, còn tôi thì chỉ muốn tìm cái góc nào có ổ điện để cắm sạc.', 'Hòa đồng, thích giao du', 'advanced', 1240),
  ('v035', 'impetuous', 'Đừng có IMPETUOUS mà chốt mua cái bàn phím 5 củ đó, cuối tháng ăn mì tôm bây giờ.', 'Hấp tấp, bốc đồng', 'advanced', 1260),
  ('v036', 'juxtapose', 'Thử JUXTAPOSE cái hình sống ảo trên mạng với cái mặt thật lúc vừa ngủ dậy đi, đảm bảo trầm cảm.', 'Đặt cạnh nhau để so sánh', 'advanced', 1230),
  ('v037', 'malevolent', 'Cái nụ cười MALEVOLENT của bà chị HR khi bảo ''Em ở lại họp tí nhé'' làm tôi thấy lạnh cả sống lưng.', 'Độc ác, có ác ý', 'advanced', 1270),
  ('v038', 'obfuscate', 'Đừng có dùng mấy cái thuật ngữ chuyên môn để OBFUSCATE cái lỗi sơ đẳng của ông, tôi biết thừa ông quên handle lỗi.', 'Làm mờ mịt, che giấu', 'advanced', 1290),
  ('v039', 'parsimony', 'Công ty này thực hành chính sách PARSIMONY cực độ, đến cái khăn giấy trong toilet cũng phải tiết kiệm.', 'Sự bủn xỉn, keo kiệt', 'advanced', 1210),
  ('v040', 'quintessential', 'Ăn bát phở vỉa hè lúc sáng sớm là một trải nghiệm QUINTESSENTIAL khi ở Việt Nam rồi.', 'Tinh túy, điển hình', 'advanced', 1200),
  ('v041', 'recalcitrant', 'Cái con chatbot RECALCITRANT này, dạy mãi mà nó vẫn cứ trả lời kiểu huề vốn.', 'Ngoan cố, bướng bỉnh', 'expert', 1350),
  ('v042', 'salient', 'Điểm SALIENT nhất trong cái CV của ông là ''biết nấu mì tôm'', còn kỹ năng code thì chưa thấy đâu.', 'Nổi bật, đáng chú ý', 'expert', 1320),
  ('v043', 'taciturn', 'Bình thường ông ấy TACITURN lắm, nhưng cứ nhắc đến chuyện lương lậu là nói như súng liên thanh.', 'Ít nói, lầm lì', 'expert', 1340),
  ('v044', 'vicarious', 'Không có tiền đi du lịch nên tôi toàn ngồi xem vlog của mấy ông travel blogger để hưởng thụ VICARIOUS.', 'Trải nghiệm gián tiếp', 'expert', 1310),
  ('v045', 'zealot', 'Mấy ông ZEALOT của một cái framework nào đó thường rất hay đi gây chiến với cộng đồng framework khác.', 'Người cuồng tín', 'expert', 1330),
  ('v046', 'ameliorate', 'Tôi đang cố AMELIORATE cái mối quan hệ với sếp bằng cách đi làm đúng giờ, dù hơi khó.', 'Cải thiện, làm tốt hơn', 'expert', 1360),
  ('v047', 'cacophony', 'Sáng sớm mà tiếng còi xe, tiếng karaoke hàng xóm trộn vào nhau tạo thành một bản CACOPHONY nhức cả đầu.', 'Âm thanh hỗn tạp, chói tai', 'expert', 1380),
  ('v048', 'dogmatic', 'Làm việc với mấy ông DOGMATIC mệt lắm, lúc nào cũng khư khư giữ cái tư duy cũ rích không chịu đổi mới.', 'Giáo điều, độc đoán', 'expert', 1300),
  ('v049', 'enervate', 'Ngồi họp 3 tiếng đồng hồ liên tục chỉ để nghe sếp hứa hẹn làm tôi thấy bị ENERVATE hoàn toàn.', 'Làm suy yếu, làm kiệt sức', 'expert', 1390),
  ('v050', 'hackneyed', 'Mấy cái câu quote ''Vượt qua giới hạn bản thân'' nghe HACKNEYED quá rồi, có cái gì mới hơn không?', 'Sáo rỗng, tầm thường', 'expert', 1410),
  ('v051', 'grandiloquent', 'Cái văn phong GRANDILOQUENT của ông nghe thì sang đấy, nhưng thực tế là chẳng ai hiểu ông muốn nói gì.', 'Khoa trương, hoa mỹ', 'expert', 1450),
  ('v052', 'iconoclast', 'Hắn ta đúng là một ICONOCLAST khi dám lên tiếng phản đối cái quy trình mà cả công ty đã dùng 10 năm nay.', 'Người đả phá những quan điểm cũ', 'expert', 1440),
  ('v053', 'laconic', 'Câu trả lời LACONIC ''Không'' của cô ấy làm tôi hiểu rằng mình không còn cơ hội nào nữa rồi.', 'Ngắn gọn, súc tích', 'expert', 1430),
  ('v054', 'obsequious', 'Nhìn cái cách ông kia OBSEQUIOUS với sếp mà tôi thấy phát ngốt, nịnh hót vừa thôi chứ.', 'Khúm núm, xu nịnh', 'expert', 1460),
  ('v055', 'pernicious', 'Cái thói quen so sánh mình với người khác trên mạng xã hội là một thói quen PERNICIOUS cho sức khỏe tinh thần.', 'Độc hại, nguy hiểm ngầm', 'expert', 1470),
  ('v056', 'quixotic', 'Cái kế hoạch xây dựng một mạng xã hội mới để lật đổ Facebook nghe có vẻ QUIXOTIC quá không Long?', 'Viển vông, không thực tế', 'expert', 1480),
  ('v057', 'risible', 'Lý do đi muộn của anh ấy thật sự RISIBLE vãi, bảo là bị... người ngoài hành tinh bắt cóc.', 'Đáng cười, lố bịch', 'expert', 1400),
  ('v058', 'sycophant', 'Ông đừng có làm cái trò SYCOPHANT đó nữa, sếp thừa biết ông nịnh để xin tăng lương thôi.', 'Kẻ nịnh hót', 'expert', 1490),
  ('v059', 'vitriolic', 'Mấy cái comment VITRIOLIC trên mạng đôi khi có thể giết chết một con người đấy, bớt khẩu nghiệp lại.', 'Châm chọc, cay độc', 'expert', 1460),
  ('v060', 'abstruse', 'Cái bài báo khoa học này viết bằng thuật ngữ gì mà ABSTRUSE thế không biết, đọc xong còn thấy lú hơn lúc chưa đọc.', 'Thâm thúy, khó hiểu', 'expert', 1490),
  ('v061', 'anxious', 'Cứ mỗi lần sếp nhắn ''Em có rảnh không'' là tôi lại thấy ANXIOUS ngang, dù chẳng làm gì sai.', 'Lo lắng, bồn chồn', 'beginner', 810),
  ('v062', 'blunt', 'Thằng bạn tôi nó BLUNT lắm, nó bảo ''Code ông rác vãi'' mà tôi không biết nên khóc hay cười.', 'Thẳng thắn đến mức thô lỗ', 'beginner', 820),
  ('v063', 'cautious', 'Phải CAUTIOUS khi bấm vào mấy cái link lạ trên Telegram, không là bay màu cái ví crypto ngay.', 'Thận trọng, cẩn thận', 'beginner', 815),
  ('v064', 'demand', 'Khách hàng DEMAND thêm tính năng mới nhưng lại không muốn chi thêm một đồng nào.', 'Yêu cầu, đòi hỏi', 'beginner', 830),
  ('v065', 'efficient', 'Dùng phím tắt là cách EFFICIENT nhất để code nhanh mà không bị sếp soi là đang lười.', 'Hiệu quả, năng suất', 'beginner', 840),
  ('v066', 'flexible', 'Thời gian làm việc ở đây khá FLEXIBLE, miễn là ông nộp task đúng hạn thì ông ngủ đến trưa cũng được.', 'Linh hoạt, dễ thích nghi', 'beginner', 835),
  ('v067', 'genuine', 'Cái nụ cười GENUINE của crush làm tôi quên hết mệt mỏi sau một ngày bị bug hành.', 'Thật thà, chân thành', 'beginner', 845),
  ('v068', 'hesitate', 'Đừng HESITATE khi thấy lương không xứng đáng với công sức, cứ mạnh dạn mà deal lại.', 'Do dự, ngập ngừng', 'beginner', 830),
  ('v069', 'impact', 'Cái đợt layoff vừa rồi có IMPACT cực lớn đến tâm lý của anh em trong team.', 'Tác động, ảnh hưởng mạnh', 'beginner', 825),
  ('v070', 'justify', 'Làm sao để JUSTIFY cái việc tôi ngủ gật trong cuộc họp là do ''đang suy nghĩ quá sâu'' đây?', 'Biện minh, thanh minh', 'beginner', 850),
  ('v071', 'keen', 'Tôi rất KEEN với mấy cái framework mới, nhưng lười học quá nên toàn đọc qua loa.', 'Hăng hái, nhiệt tình', 'beginner', 835),
  ('v072', 'logical', 'Giải thích kiểu gì cho LOGICAL một tí đi, đừng có đổ thừa tại máy tính nó tự xóa file nữa.', 'Hợp lý, theo logic', 'beginner', 840),
  ('v073', 'massive', 'Có một sự MASSIVE khác biệt giữa việc ''biết code'' và ''biết code sạch''.', 'Khổng lồ, to lớn', 'beginner', 820),
  ('v074', 'neglect', 'Vì quá mải mê fix bug mà tôi NEGLECT luôn cả việc ăn tối, giờ thì đau dạ dày rồi.', 'Bỏ bê, xao nhãng', 'beginner', 855),
  ('v075', 'obvious', 'Lỗi syntax sờ sờ ra đó mà tìm mãi không thấy, đúng là OBVIOUS quá nên mới mù quáng.', 'Rõ ràng, hiển nhiên', 'beginner', 815),
  ('v076', 'persistent', 'Mấy cái quảng cáo nhà đất nó PERSISTENT gọi cho tôi cả ngày, block số này nó gọi số khác.', 'Kiên trì, dai dẳng', 'beginner', 860),
  ('v077', 'relevant', 'Nói chuyện vào trọng tâm đi ông ơi, mấy cái ví dụ này không RELEVANT gì đến vấn đề mình đang gặp cả.', 'Liên quan, phù hợp', 'beginner', 845),
  ('v078', 'significant', 'Tìm được một con mentor tốt sẽ tạo ra thay đổi SIGNIFICANT cho con đường sự nghiệp của ông.', 'Quan trọng, đáng kể', 'beginner', 850),
  ('v079', 'tolerate', 'Tôi không thể TOLERATE nổi cái thói lười biếng mà còn hay đổ lỗi của ông đồng nghiệp cùng team.', 'Tha thứ, chịu đựng', 'beginner', 855),
  ('v080', 'utilize', 'Phải biết cách UTILIZE tối đa sức mạnh của AI để làm việc nhanh hơn, chứ đừng để nó thay thế mình.', 'Sử dụng, tận dụng', 'beginner', 860),
  ('v081', 'valid', 'Cái argument của ông nghe cũng VALID đấy, nhưng áp dụng vào thực tế thì chắc chắn là tạch.', 'Hợp lệ, có cơ sở', 'beginner', 840),
  ('v082', 'willing', 'Tôi WILLING làm thêm giờ nếu công ty trả lương OT sòng phẳng, còn không thì cứ 5h là ''phắn''.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v083', 'abstract', 'Mấy cái định nghĩa về Clean Architecture này nghe ABSTRACT quá, cho tôi ví dụ code thực tế đi.', 'Trừu tượng', 'beginner', 870),
  ('v084', 'benefit', 'Làm ở công ty lớn thì BENEFIT tốt thiệt, nhưng bù lại là quy trình rườm rà phát mệt.', 'Lợi ích, phúc lợi', 'beginner', 825),
  ('v085', 'confident', 'Lúc phỏng vấn thì CONFIDENT lắm, vô làm thật mới biết mình còn non và xanh như trái chuối.', 'Tự tin', 'beginner', 835),
  ('v086', 'diverse', 'Bộ sưu tập cốc cà phê của tôi DIVERSE hơn cả kinh nghiệm sống.', 'Đa dạng', 'beginner', 865),
  ('v087', 'evident', 'EVIDENT là tôi không ngủ đủ giấc: mắt tôi trông như panda mỗi sáng.', 'Rõ ràng, hiển nhiên', 'beginner', 855),
  ('v088', 'focus', 'FOCUS của tôi kéo dài đúng bằng thời gian YouTube ad trước khi skip được.', 'Tập trung', 'beginner', 820),
